      },
      "hair_color": {
        "source": "image",
        "image_locked": true
      },
      "eye_color": {
        "source": "image",
        "image_locked": true
      }
    },
    "pose": {
      "source": "image",
      "image_locked": true,
      "allowed_sources": [
        "text",
        "image"
      ]
    },
    "expression": {
      "allowed_sources": [
        "text",
        "image"
