        "text",
        "image"
      ],
      "forbid_value_generation": true,
      "source": "image",
      "image_locked": true
    }
  },
  "quality_controls": {
    "forbidden_changes": [
      "modifying identity attributes sourced from image",
      "implicit face or hair alteration",
      "beautification or aging",
      "conflicting multiple values for a single attribute"
    ]
  }
